-- Newsletter DRAFTS generated by scripts/newsletter-drafts/build.mts.
-- Inserts as status 'draft' / stage 'early'; nothing here schedules or sends.
-- Skips any draft whose title already exists. Safe to re-run.

-- friday-lunch-event-week-offers
insert into public.newsletters
  (title, subject, preheader, audience, blocks, status, stage)
select
  'Signal: Friday event week offers',
  'Dinner tonight? Breakfast tomorrow?',
  'It''s not too late to enjoy our event week offers at venues around Newcastle.',
  'ticket-purchasers',
  $nl$[{"id":"friday-lunch-event-week-offers-01","type":"image","src":"https://tedxnewy.com.au/images/newsletter/signal-hero.jpg","alt":"A packed audience at a TEDxNewy event","widthPct":"full"},{"id":"friday-lunch-event-week-offers-02","type":"header","text":"Thinking about dinner tonight?","size":"lg"},{"id":"friday-lunch-event-week-offers-03","type":"text","html":"<p>Or breakfast tomorrow?</p><p>It's not too late to enjoy our event week offers. Local venues around Newcastle have put together something special for ticket holders, and a few of them are waiting for you tonight and tomorrow morning.</p><p>Just show your ticket or email confirmation.</p>"},{"id":"friday-lunch-event-week-offers-04","type":"header","text":"Dinner and drinks tonight","size":"md"},{"id":"friday-lunch-event-week-offers-05","type":"columns","cols":[[{"id":"friday-lunch-event-week-offers-05-i","kind":"image","src":"https://tedxnewy.com.au/images/newsletter/venue-lolas.jpg","alt":"A table at LOLAs on Darby Street","widthPct":100,"ratio":"4:3"}],[{"id":"friday-lunch-event-week-offers-05-t","kind":"text","html":"<p><strong>LOLAs</strong><br>A Darby St favourite for lunch, dinner and a drink.</p><p><strong>Free TEDx Spritz with your meal.</strong></p>"},{"id":"friday-lunch-event-week-offers-05-b","kind":"button","label":"Book a table","href":"https://www.sevenrooms.com/landing/lolasdarbystreetnewcastle","align":"left","theme":"red","variant":"solid"}]],"ratio":"40-60","valign":"middle"},{"id":"friday-lunch-event-week-offers-06","type":"divider","style":"thin","colour":"soft"},{"id":"friday-lunch-event-week-offers-07","type":"columns","cols":[[{"id":"friday-lunch-event-week-offers-07-i","kind":"image","src":"https://tedxnewy.com.au/images/newsletter/venue-kingfish.jpg","alt":"The Kingfish at Honeysuckle","widthPct":100,"ratio":"4:3"}],[{"id":"friday-lunch-event-week-offers-07-t","kind":"text","html":"<p><strong>The Kingfish</strong><br>Waterfront dining at Honeysuckle. A drink, a meal and dessert by the water.</p><p><strong>Free bottle of house wine with a seafood platter.</strong></p>"},{"id":"friday-lunch-event-week-offers-07-b","kind":"button","label":"Book a table","href":"https://www.sevenrooms.com/explore/thekingfish/reservations/create/search?venues=thekingfish%2Cblanca","align":"left","theme":"red","variant":"solid"}]],"ratio":"40-60","valign":"middle"},{"id":"friday-lunch-event-week-offers-08","type":"divider","style":"thin","colour":"soft"},{"id":"friday-lunch-event-week-offers-09","type":"columns","cols":[[{"id":"friday-lunch-event-week-offers-09-i","kind":"image","src":"https://tedxnewy.com.au/images/newsletter/venue-grain-store.jpg","alt":"The Grain Store taproom in East End","widthPct":100,"ratio":"4:3"}],[{"id":"friday-lunch-event-week-offers-09-t","kind":"text","html":"<p><strong>The Grain Store</strong><br>Twenty one taps of independent beer in an old East End grain warehouse.</p><p><strong>Limited TEDx IPA while stock lasts, and $7 schooners (usually $12).</strong></p>"},{"id":"friday-lunch-event-week-offers-09-b","kind":"button","label":"Book a table","href":"https://www.grainstore.beer/online-booking/","align":"left","theme":"red","variant":"solid"}]],"ratio":"40-60","valign":"middle"},{"id":"friday-lunch-event-week-offers-10","type":"divider","style":"short","colour":"soft"},{"id":"friday-lunch-event-week-offers-11","type":"header","text":"Breakfast tomorrow","size":"md"},{"id":"friday-lunch-event-week-offers-12","type":"text","html":"<p>Doors open at 1:30pm tomorrow, so there's plenty of time for a slow morning.</p>"},{"id":"friday-lunch-event-week-offers-13","type":"columns","cols":[[{"id":"friday-lunch-event-week-offers-13-i","kind":"image","src":"https://tedxnewy.com.au/images/newsletter/venue-one-penny-black.jpg","alt":"One Penny Black on Hunter Street","widthPct":100,"ratio":"4:3"}],[{"id":"friday-lunch-event-week-offers-13-t","kind":"text","html":"<p><strong>One Penny Black</strong><br>A Newcastle institution on Hunter St, with specialty coffee, big breakfasts and lunch.</p><p><strong>20% off your order.</strong></p>"},{"id":"friday-lunch-event-week-offers-13-b","kind":"button","label":"Get directions","href":"https://www.google.com/maps/dir/?api=1&destination=One+Penny+Black%2C+196+Hunter+St%2C+Newcastle+NSW","align":"left","theme":"ink","variant":"outline"}]],"ratio":"40-60","valign":"middle"},{"id":"friday-lunch-event-week-offers-14","type":"divider","style":"thin","colour":"soft"},{"id":"friday-lunch-event-week-offers-15","type":"columns","cols":[[{"id":"friday-lunch-event-week-offers-15-i","kind":"image","src":"https://tedxnewy.com.au/images/newsletter/venue-momo-wholefood.jpg","alt":"Momo Wholefood in the heritage bank building on Hunter Street","widthPct":100,"ratio":"4:3"}],[{"id":"friday-lunch-event-week-offers-15-t","kind":"text","html":"<p><strong>Momo Wholefood</strong><br>Fresh, seasonal wholefood in a heritage bank building on the corner of Hunter and Brown Streets. Plenty of vegan and vegetarian options.</p><p><strong>Free small coffee with any main.</strong></p>"},{"id":"friday-lunch-event-week-offers-15-b","kind":"button","label":"Get directions","href":"https://www.google.com/maps/dir/?api=1&destination=Momo+Wholefood%2C+227+Hunter+St%2C+Newcastle+NSW","align":"left","theme":"ink","variant":"outline"}]],"ratio":"40-60","valign":"middle"},{"id":"friday-lunch-event-week-offers-16","type":"divider","style":"short","colour":"soft"},{"id":"friday-lunch-event-week-offers-17","type":"header","text":"See you tomorrow","size":"md"},{"id":"friday-lunch-event-week-offers-18","type":"text","html":"<p><strong>Saturday 24 October 2026</strong><br>Doors open at 1:30pm<br>Conservatorium of Music, corner Laman Street and Auckland Street, Newcastle</p><p>There are more offers across Newcastle in the Event Week Guide, if you'd like to see what else is on.</p>"},{"id":"friday-lunch-event-week-offers-19","type":"button","label":"See all event week offers","href":"https://tedxnewy.com.au/downloads/make-the-most-of-event-week-guide.pdf","align":"center","theme":"ink","variant":"outline"},{"id":"friday-lunch-event-week-offers-20","type":"text","html":"<p>Will and the TEDxNewy team</p>"}]$nl$::jsonb,
  'draft',
  'early'
where not exists (
  select 1 from public.newsletters where title = 'Signal: Friday event week offers'
);
